ANNOTATIONS = [
    (4, 'before', r'''文件定位：从 TeammateTool 抽出来的共享 spawn 模块，AgentTool 也复用它——「造一个队友」的完整逻辑只此一份。'''),
    (70, 'after', r'''导入清单就是能力地图：registry（后端探测）、teammateLayoutManager（tmux/iTerm2 面板管理）、spawnInProcess（进程内队友）、teamHelpers（团队文件读写）、teammateMailbox（首条指令投递）。'''),
    (82, 'after', r'''getDefaultTeammateModel 三级兜底：配置为 null（用户在 /config 选了 Default）→ 跟随 leader；配置有值 → parseUserSpecifiedModel；两者都没有 → 硬编码回退模型。'''),
    (101, 'after', r'''resolveTeammateModel 处理 'inherit' 别名（agent frontmatter 里写的）。gh-31069：'inherit' 曾字面量传给 --model，报「It may not exist or you may not have access」；leader 模型未定时落到默认。'''),
    (120, 'after', r'''SpawnOutput 里 tmux_session/window/pane 三个字段是给老 transcript 兼容的——in-process 模式也填 'in-process' 占位，消费方不用判模式。'''),
    (136, 'after', r'''invokingRequestId 注释说明了用途：把 spawn 归因到「哪个 API 回合的响应触发了它」，用于 tengu_api_* 事件的血缘追踪。'''),
    (150, 'after', r'''SpawnInput 与 SpawnTeammateConfig 同构——内部版保持 TeammateTool 原有参数形态，少一层转换。'''),
    (166, 'after', r'''hasSession 用 execFileNoThrow（不抛异常版）：tmux has-session 退出码 0 即会话存在。'''),
    (186, 'after', r'''ensureSession 用 -d 建 detached 会话；创建失败把 stderr 原样带进错误信息。'''),
    (198, 'after', r'''getTeammateCommand：原生构建（编译出的二进制）用 process.execPath，脚本运行（node/bun 跑 JS）用 process.argv[1]；环境变量 TEAMMATE_COMMAND_ENV_VAR 可强制覆盖。'''),
    (260, 'after', r'''buildInheritedCliFlags 把 leader 的会话状态翻译成子进程 CLI 参数。权限传播有条硬优先级：plan_mode_required 压过 bypassPermissions（安全压倒便利）；auto 模式也传给队友，让它的分类器同样自动放行。model/settings/plugin-dir/chrome 逐个从 bootstrap state 取——队友是全新进程，env 不传就全丢。'''),
    (294, 'after', r'''generateUniqueTeammateName：重名追加数字后缀（tester-2、tester-3）；比较一律 toLowerCase，大小写不同也算撞名。'''),
    (317, 'after', r'''name 和 prompt 是 spawn 的最小集——没有指令的队友没有存在意义。'''),
    (327, 'after', r'''team_name 双来源：输入参数或 leader 的 teamContext。错误信息直接指明解法（先调 spawnTeam 建立团队上下文），不是干巴巴的「缺少参数」。'''),
    (333, 'after', r'''sanitizeAgentName 防 @ 混进名字——agentId 格式是 name@teamName，一个 @ 就能把格式破坏掉。'''),
    (336, 'after', r'''formatAgentId 确定性生成：同名同队永远得到同一 ID，重复 spawn 是幂等的。'''),
    (357, 'after', r'''iTerm2 里 it2 没装好时弹 It2SetupPrompt——把 setToolJSX 回调包成 Promise，工具执行流可以 await 用户决策。'''),
    (375, 'after', r'''用户装好 it2 或选「改用 tmux」后 resetBackendDetection 强制重探测——不清缓存的话本地 detectionResult 和真正 spawn 面板的后端不一致，后面全错。'''),
    (397, 'after', r'''enablePaneBorderStatus 只在 tmux 内且是第一个队友时调；tmux 外由 createTeammatePaneInSwarmView 自己处理。'''),
    (414, 'after', r'''身份四件套（agent-id/name/team-name/color）走 CLI 参数而非 CLAUDE_CODE_* 环境变量——注释明说 replaces。注意 spawn 命令不带 prompt：初始指令经 mailbox 发送，见下面 writeToMailbox。'''),
    (434, 'after', r'''队友自定义 model 时覆盖继承来的 --model：先按词过滤掉旧的 flag 对（flag 本身和它的前一个词），再追加新的——字符串 split 手工去 flag，没用命令行解析器。'''),
    (440, 'after', r'''spawnCommand 拼装：cd 工作目录 + env 传继承变量 + quote 包二进制路径（防空格）+ 身份参数 + 继承 flag。'''),
    (444, 'after', r'''sendCommandToPane 第三个参数 !insideTmux 是「用不用 swarm socket」：tmux 内直连当前 session，tmux 外（iTerm2/外部 swarm session）才走 socket。'''),
    (472, 'after', r'''teamContext 更新：teammates map 加一条（名字/类型/颜色/pane/cwd/时间戳），UI 的任务 pill 和团队面板都读这个。'''),
    (486, 'after', r'''registerOutOfProcessTeammateTask：tmux 队友也注册成后台任务——和进程内队友一样出现在任务列表里，用户能看到。'''),
    (509, 'after', r'''teamFile.members.push 后写回——团队文件是队友名录的持久化，resume 和跨会话同步靠它。'''),
    (521, 'after', r'''首条指令走 mailbox：队友启动后 inbox poller 会捡起来当第一轮用户消息提交——「spawn 不带 prompt」的谜底在这里。'''),
    (538, 'after', r'''返回数据里 is_splitpane: true 标记这条输出来自 split-pane 路径（单窗口路径为 false）。'''),
    (602, 'after', r'''new-window 用 -P -F '#{pane_id}' 打印模式直接拿 pane id——不用解析窗口列表，格式由自己指定。'''),
    (700, 'after', r'''backendType 硬编码 'tmux'：这个 handler 永远直接操作 tmux，不经过 registry 探测。'''),
    (753, 'after', r'''is_splitpane: false + tmux_* 填真实 session/window 名。'''),
    (817, 'after', r'''taskState 组装：type 复用 'in_process_teammate'（哪怕是 tmux 队友，UI 层按这个类型渲染）；permissionMode 由 plan_mode_required 决定——plan 队友天生不能乱改文件。'''),
    (833, 'after', r'''abort 监听 once: true。注释说明分工：SDK task_notification 的 bookend 由 killInProcessTeammate 发（唯一的 abort 触发器），这里只负责按创建它的后端杀 pane。'''),
    (887, 'after', r'''agent_type 查 CustomAgentDefinition：只有自定义代理（loadAgentsDir 加载的）才有 definition；found 结果进 debug 日志，排查「自定义代理没生效」类问题。'''),
    (908, 'after', r'''startInProcessTeammate 是 fire-and-forget：不 await，主循环不等队友跑完——队友在自己的 AsyncLocalStorage 上下文里独立循环。'''),
    (931, 'after', r'''messages: [] 是这个文件最重要的注释之一：绝不把父对话传给队友。传了会钉住整个会话历史，/clear 和 auto-compact 都救不回来——队友自己经 inProcessRunner 的 allMessages 建历史。'''),
    (986, 'after', r'''自动补 leader：没有 leadAgentId 时先把自己注册成 lead——inbox 轮询需要 leader 也在 teammates map 里。'''),
    (1009, 'after', r'''注意 in-process 不走 mailbox：prompt 已由 startInProcessTeammate 直接给了，双发会产生两条欢迎语。'''),
    (1031, 'after', r'''is_splitpane: false，tmux_* 三字段填 'in-process' 占位。'''),
    (1069, 'after', r'''handleSpawn 路由：isInProcessEnabled → 进程内；否则预探测 pane 后端。探测失败只在 auto 模式静默回退——用户显式配了 teammateMode: 'tmux' 就让错误抛出去，好看安装指引。markInProcessFallback 把回落写回状态，banner 不再显示 tmux attach 命令。'''),
    (1077, 'after', r'''use_splitpane !== false 走 split-pane（默认）；显式传 false 才走老的「一个队友一个窗口」路径。'''),
    (1092, 'after', r'''spawnTeammate 是唯一出口：TeammateTool 和 AgentTool 都经这里 spawn，内部路由对调用方透明。'''),
]
